(() => {
  'use strict';
  if(window.__kredrunAccountLifecycleKickLoaded)return;window.__kredrunAccountLifecycleKickLoaded=true;
  const client=window.kredrunSupabase;if(!client)return;
  async function kick(){try{const{data}=await client.auth.getSession();const token=data?.session?.access_token;if(!token)return;await fetch('/api/lifecycle',{method:'POST',headers:{Authorization:`Bearer ${token}`},keepalive:true,signal:AbortSignal.timeout(25000)});}catch(error){console.warn('Account lifecycle processing will retry automatically.',error);}}
  setTimeout(kick,900);
  document.addEventListener('click',event=>{if(event.target.closest('[data-pay-loan],[data-settle-loan]'))setTimeout(kick,3500);});
})();

(() => {
  'use strict';
  const client = window.kredrunSupabase;
  if (!client || window.__kredrunAccountPaymentsLoaded) return;
  window.__kredrunAccountPaymentsLoaded = true;

  const money = value => `R${new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(value || 0))}`;

  function settlementModal() {
    let modal = document.querySelector('[data-settlement-modal]');
    if (modal) return modal;
    modal = document.createElement('div');
    modal.className = 'payment-modal';
    modal.dataset.settlementModal = '';
    modal.hidden = true;
    modal.innerHTML = `
      <div class="payment-modal__backdrop" data-settlement-cancel></div>
      <section class="payment-modal__card" role="dialog" aria-modal="true" aria-labelledby="settlement-modal-title" aria-describedby="settlement-modal-copy" tabindex="-1">
        <button class="payment-modal__close" type="button" aria-label="Close settlement confirmation" data-settlement-cancel>&times;</button>
        <div class="payment-modal__icon" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false"><path d="M12 3 4.8 6.2v4.9c0 4.5 3 8.6 7.2 9.9 4.2-1.3 7.2-5.4 7.2-9.9V6.2L12 3Zm3.2 6.9-3.8 4.3a1 1 0 0 1-1.5.1l-2-1.9 1.4-1.5 1.2 1.2 3.2-3.6 1.5 1.4Z"/></svg></div>
        <p class="payment-modal__eyebrow">Early settlement</p>
        <h2 id="settlement-modal-title">Settle this loan?</h2>
        <p id="settlement-modal-copy" class="payment-modal__copy">Please review your settlement amount before continuing.</p>
        <div class="payment-modal__amount"><span>Total settlement amount</span><strong data-settlement-amount></strong></div>
        <div class="payment-modal__saving" data-settlement-saving hidden><span>You save</span><strong data-settlement-rebate></strong><small>Future interest and service fees</small></div>
        <p class="payment-modal__note">Your loan will only be settled after the selected payment provider confirms the payment.</p>
        <div class="payment-modal__actions"><button class="payment-modal__button payment-modal__button--secondary" type="button" data-settlement-cancel>Cancel</button><button class="payment-modal__button payment-modal__button--primary" type="button" data-settlement-continue>Continue</button></div>
      </section>`;
    document.body.append(modal);
    return modal;
  }

  function confirmSettlement(amount, rebate) {
    const modal = settlementModal();
    const card = modal.querySelector('.payment-modal__card');
    const continueButton = modal.querySelector('[data-settlement-continue]');
    const saving = modal.querySelector('[data-settlement-saving]');
    const focusable = [...modal.querySelectorAll('button:not([disabled])')];
    const previousFocus = document.activeElement;
    modal.querySelector('[data-settlement-amount]').textContent = money(amount);
    modal.querySelector('[data-settlement-rebate]').textContent = money(rebate);
    saving.hidden = !(rebate > 0);
    modal.hidden = false;
    document.body.classList.add('payment-modal-open');
    return new Promise(resolve => {
      const finish = confirmed => {
        modal.hidden = true; document.body.classList.remove('payment-modal-open');
        modal.removeEventListener('click', onClick); document.removeEventListener('keydown', onKeydown);
        if (!confirmed && previousFocus instanceof HTMLElement && previousFocus.isConnected) previousFocus.focus();
        resolve(confirmed);
      };
      const onClick = event => { if (event.target.closest('[data-settlement-continue]')) finish(true); else if (event.target.closest('[data-settlement-cancel]')) finish(false); };
      const onKeydown = event => {
        if (event.key === 'Escape') return finish(false);
        if (event.key !== 'Tab' || focusable.length < 2) return;
        const first = focusable[0], last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      };
      modal.addEventListener('click', onClick); document.addEventListener('keydown', onKeydown);
      requestAnimationFrame(() => { card.classList.add('payment-modal__card--open'); continueButton.focus(); window.setTimeout(() => card.classList.remove('payment-modal__card--open'), 260); });
    });
  }

  function notice(message, type = 'info') {
    let region = document.querySelector('[data-payment-notice]');
    if (!region) { region = document.createElement('div'); region.dataset.paymentNotice = ''; region.className = 'payment-notice'; document.body.append(region); }
    region.className = `payment-notice ${type}`; region.textContent = message; region.hidden = false;
    window.setTimeout(() => { if (region.isConnected) region.hidden = true; }, 6500);
  }

  async function accessToken() {
    const { data } = await client.auth.getSession();
    const token = data?.session?.access_token;
    if (!token) throw new Error('Please sign in again.');
    return token;
  }

  async function api(path, options = {}) {
    const token = await accessToken();
    const response = await fetch(path, { ...options, headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', ...(options.headers || {}) }, signal: AbortSignal.timeout(25000) });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || !payload.ok) throw new Error(payload.message || 'The payment request could not be completed.');
    return payload;
  }

  async function startPayment(button, paymentType) {
    if (button.dataset.running === 'true') return;
    button.dataset.running = 'true'; button.disabled = true;
    const original = button.textContent;
    try {
      button.textContent = paymentType === 'settlement' ? 'Calculating settlement…' : 'Preparing payment…';
      const loanId = button.dataset.payLoan || button.dataset.settleLoan;
      const query = new URLSearchParams({ loanId, paymentType });
      const quote = await api(`/api/payments/quote?${query}`);
      if (paymentType === 'settlement') {
        const rebate = Number(quote.breakdown?.future_charge_rebate || 0);
        if (!await confirmSettlement(quote.amount, rebate)) return;
      }
      button.textContent = `Starting ${quote.providerName || 'payment'}…`;
      const payment = await api('/api/payments/start', { method:'POST', body:JSON.stringify({ loanId, paymentType, scheduleId:quote.scheduleId }) });
      if (payment.interaction === 'redirect' && payment.authorizationUrl) {
        window.location.assign(payment.authorizationUrl);
        return;
      }
      notice(payment.message || `${payment.providerName || 'The payment provider'} is processing your payment request.`, 'success');
    } catch (error) {
      notice(error.message || 'The payment could not be started.', 'error');
    } finally {
      if (button.isConnected) { delete button.dataset.running; button.disabled = false; button.textContent = original; }
    }
  }

  document.addEventListener('click', event => {
    const pay = event.target.closest('[data-pay-loan]'); if (pay) return startPayment(pay, 'instalment');
    const settle = event.target.closest('[data-settle-loan]'); if (settle) return startPayment(settle, 'settlement');
  });

  (async () => {
    const params = new URLSearchParams(window.location.search);
    const paymentState = params.get('payment');
    if (paymentState === 'success') { history.replaceState(null, '', 'account.html'); notice('Payment confirmed. Your loan balance and instalment have been updated.', 'success'); return; }
    if (paymentState === 'request') { history.replaceState(null, '', 'account.html'); notice('Thank you. Your payment provider is confirming the payment and your balance will update shortly.', 'success'); return; }
    if (paymentState !== 'verify') return;
    const reference = params.get('reference') || params.get('trxref');
    const provider = params.get('provider');
    if (!reference || !provider) { history.replaceState(null, '', 'account.html'); notice('The payment provider did not return enough information to verify this payment.', 'error'); return; }
    try {
      notice('Confirming your payment…');
      const query = new URLSearchParams({ provider, reference });
      await api(`/api/payments/verify?${query}`);
      window.location.replace('account.html?payment=success');
    } catch (error) {
      history.replaceState(null, '', 'account.html');
      notice(error.message || 'The payment could not be confirmed yet.', 'error');
    }
  })();
})();

(() => {
  const body = document.body;
  if (!body?.classList.contains('account-page')) return;

  const greeting = document.querySelector('[data-account-greeting]');
  const applications = document.querySelector('[data-overview-applications]');
  const loans = document.querySelector('[data-overview-loans]');
  const payment = document.querySelector('[data-overview-payment]');
  const applicationList = document.querySelector('[data-applications-list]');
  const loanList = document.querySelector('[data-loans-list]');

  const text = element => String(element?.textContent || '').replace(/\s+/g, ' ').trim();
  const baseDataReady = () => {
    const name = text(greeting);
    const applicationSummary = text(applications);
    const loanSummary = text(loans);
    const paymentSummary = text(payment);
    const listsReady = !applicationList?.querySelector('.portal-loading') && !loanList?.querySelector('.portal-loading');
    const applicationStatusReady = Boolean(applicationSummary) && !/^\d+$/.test(applicationSummary) && !/loading/i.test(applicationSummary);

    return Boolean(name && name.toLowerCase() !== 'there')
      && applicationStatusReady
      && Boolean(loanSummary)
      && Boolean(paymentSummary) && !/loading/i.test(paymentSummary)
      && listsReady;
  };

  const reveal = () => {
    if (!body.classList.contains('account-booting')) return;
    body.classList.remove('account-booting');
    body.classList.add('account-ready');
    document.querySelector('[data-account-boot]')?.setAttribute('aria-hidden', 'true');
  };

  const started = performance.now();
  const check = () => {
    if (baseDataReady()) return reveal();
    if (performance.now() - started > 8000) return reveal();
    window.setTimeout(check, 60);
  };

  check();
})();

(() => {
  'use strict';
  if(window.__kredrunSettlementLettersLoaded)return;window.__kredrunSettlementLettersLoaded=true;
  const client=window.kredrunSupabase,host=document.querySelector('[data-loan-detail-content]');if(!client||!host)return;
  let currentLoanId=null,timer=null;
  async function token(){const{data}=await client.auth.getSession();if(!data?.session?.access_token)throw new Error('Please sign in again.');return data.session.access_token;}
  function normalizePaymentCopy(){host.querySelectorAll('.loan-payment-actions p').forEach(p=>{if(/paystack/i.test(p.textContent||''))p.textContent='Your lender’s active payment provider handles instalment payments and early settlement securely. Your balance changes only after the provider confirms payment.';});}
  async function decorate(){
    normalizePaymentCopy();
    if(!currentLoanId||host.querySelector('[data-settlement-letter-section]'))return;
    try{const response=await fetch(`/api/settlement-letter?action=list&loanId=${encodeURIComponent(currentLoanId)}`,{headers:{Authorization:`Bearer ${await token()}`},signal:AbortSignal.timeout(12000)});const payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok||!payload.letters?.length)return;const section=document.createElement('section');section.className='portal-subsection';section.dataset.settlementLetterSection='';section.innerHTML=`<h3>Settlement letter</h3><div class="document-list">${payload.letters.map(letter=>`<button class="document-row" type="button" data-open-settlement-letter="${letter.id}"><span><strong>Loan settlement confirmation</strong><small>${letter.letter_number} · ${letter.settlement_date}</small></span><b>Open</b></button>`).join('')}</div>`;host.append(section);}catch(error){console.warn('Settlement letter could not be loaded',error);}
  }
  async function openLetter(button){
    if(button.dataset.loading==='true')return;button.dataset.loading='true';button.disabled=true;const old=button.querySelector('b')?.textContent;
    try{if(button.querySelector('b'))button.querySelector('b').textContent='Opening…';const response=await fetch(`/api/settlement-letter?action=view&id=${encodeURIComponent(button.dataset.openSettlementLetter)}`,{headers:{Authorization:`Bearer ${await token()}`},signal:AbortSignal.timeout(12000)});if(!response.ok)throw new Error('Settlement letter could not be opened.');const html=await response.text(),url=URL.createObjectURL(new Blob([html],{type:'text/html'}));window.open(url,'_blank','noopener,noreferrer');setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(error){alert(error.message||'Settlement letter could not be opened.');}finally{delete button.dataset.loading;button.disabled=false;if(button.querySelector('b'))button.querySelector('b').textContent=old||'Open';}
  }
  document.addEventListener('click',event=>{const view=event.target.closest('[data-view-loan]');if(view){currentLoanId=view.dataset.viewLoan;clearTimeout(timer);timer=setTimeout(decorate,250);return;}const letter=event.target.closest('[data-open-settlement-letter]');if(letter){event.preventDefault();openLetter(letter);}});
  new MutationObserver(()=>{normalizePaymentCopy();clearTimeout(timer);timer=setTimeout(decorate,120);}).observe(host,{childList:true,subtree:true});
})();

(() => {
  const panel = document.querySelector('[data-current-application]');
  if (!panel) return;

  const summary = document.querySelector('[data-overview-applications]');
  const applicationList = document.querySelector('[data-applications-list]');
  const title = panel.querySelector('[data-current-application-title]');
  const reference = panel.querySelector('[data-current-application-reference]');
  const amountEl = panel.querySelector('[data-current-application-amount]');
  const nextEl = panel.querySelector('[data-current-application-next]');
  const viewButton = panel.querySelector('[data-view-current-application]');
  const stages = [...panel.querySelectorAll('[data-app-stage]')];
  const money = value => `R ${new Intl.NumberFormat('en-ZA', { maximumFractionDigits: 0 }).format(Number(value || 0))}`;

  const states = {
    received: { label: 'Waiting for review', summary: 'Waiting for review', next: 'Next: lender review', stage: 2, badge: 'Waiting for review' },
    submitted: { label: 'Waiting for review', summary: 'Waiting for review', next: 'Next: lender review', stage: 2, badge: 'Waiting for review' },
    pending: { label: 'Waiting for review', summary: 'Waiting for review', next: 'Next: lender review', stage: 2, badge: 'Waiting for review' },
    under_review: { label: 'In review', summary: 'In review', next: 'Next: decision', stage: 2, badge: 'In review' },
    reviewing: { label: 'In review', summary: 'In review', next: 'Next: decision', stage: 2, badge: 'In review' },
    needs_information: { label: 'Action needed', summary: 'Action needed', next: 'Next: provide requested info', stage: 2, badge: 'Action needed' },
    documents_requested: { label: 'Action needed', summary: 'Action needed', next: 'Next: provide requested info', stage: 2, badge: 'Action needed' },
    approved: { label: 'Approved', summary: 'Approved', next: 'Next: offer & payout', stage: 3, badge: 'Approved' },
    declined: { label: 'Decision made', summary: 'Decision made', next: 'View your decision', stage: 3, badge: 'Decision made' },
    rejected: { label: 'Decision made', summary: 'Decision made', next: 'View your decision', stage: 3, badge: 'Decision made' },
    cancelled: { label: 'Cancelled', summary: 'Cancelled', next: 'Application closed', stage: 3, badge: 'Cancelled' }
  };

  const renderStages = activeStage => {
    stages.forEach((stage, index) => {
      const stageNumber = index + 1;
      const complete = stageNumber < activeStage || (activeStage === 3 && stageNumber === 3);
      stage.classList.toggle('done', complete);
      stage.classList.toggle('active', stageNumber === activeStage && !complete);
      const icon = stage.querySelector('i');
      const nextIcon = complete ? '✓' : String(stageNumber);
      if (icon && icon.textContent !== nextIcon) icon.textContent = nextIcon;
    });
  };

  const relabelApplicationBadges = () => {
    if (!applicationList) return;
    applicationList.querySelectorAll('.status-badge').forEach(badge => {
      const className = [...badge.classList].find(name => name.startsWith('status-') && name !== 'status-badge');
      if (!className) return;
      const key = className.slice(7);
      const nextLabel = states[key]?.badge;
      if (nextLabel && badge.textContent !== nextLabel) badge.textContent = nextLabel;
    });
  };

  // account.js loads the application list asynchronously. Use a short, finite sync instead of
  // observing text mutations. A text MutationObserver here can trigger itself repeatedly and
  // lock the browser when a status badge is rewritten.
  const syncAfterAccountRender = applySummary => {
    relabelApplicationBadges();
    applySummary?.();
  };

  viewButton?.addEventListener('click', () => document.querySelector('[data-account-nav="applications"]')?.click());

  const renderApplication = application => {
    if (!application) {
      panel.hidden = true;
      const desired = 'None<small>No application waiting</small>';
      syncAfterAccountRender(() => {
        if (summary && summary.innerHTML !== desired) summary.innerHTML = desired;
      });
      return;
    }

    const key = String(application.status || 'received').toLowerCase();
    const state = states[key] || { label: 'Application received', summary: 'Application received', next: 'Check application for updates', stage: 2, badge: 'Application received' };

    panel.hidden = false;
    panel.dataset.status = key;
    title.textContent = state.label;
    reference.textContent = application.reference || '';
    amountEl.textContent = money(application.loan_amount);
    nextEl.textContent = state.next;
    renderStages(state.stage);

    const desired = `${state.summary}<small>${money(application.loan_amount)}</small>`;
    syncAfterAccountRender(() => {
      if (summary && summary.innerHTML !== desired) summary.innerHTML = desired;
    });
  };

  const useApplications = applications => renderApplication(Array.isArray(applications) ? applications[0] : null);
  if (Array.isArray(window.__kredrunAccountApplications)) {
    useApplications(window.__kredrunAccountApplications);
  } else {
    window.addEventListener('kredrun:account-applications', event => useApplications(event.detail?.applications), { once: true });
  }
})();

(() => {
  const client = window.kredrunSupabase;
  const auth = window.KredRunAuth;
  const profileSchema = window.KredRunClientProfile;
  if (!client || !auth || !profileSchema) return;

  const money = new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR', maximumFractionDigits: 2 });
  const dateFmt = new Intl.DateTimeFormat('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });
  const escape = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
  const amount = value => money.format(Number(value || 0)).replace('ZAR', 'R').trim();
  const date = value => {
    if (!value) return '—';
    const raw = String(value);
    const parsed = /^\d{4}-\d{2}-\d{2}$/.test(raw) ? new Date(`${raw}T00:00:00`) : new Date(raw);
    return Number.isNaN(parsed.getTime()) ? '—' : dateFmt.format(parsed);
  };
  const statusLabel = value => String(value || '').replaceAll('_', ' ').replace(/\b\w/g, c => c.toUpperCase());
  const isInternalEmail = value => /^kr-[a-f0-9]+@login\.invalid$/i.test(String(value || '').trim());
  const validEmail = value => /^\S+@\S+\.\S+$/.test(String(value || '').trim()) && !isInternalEmail(value);

  const greeting = document.querySelector('[data-account-greeting]');
  const applicationList = document.querySelector('[data-applications-list]');
  const loanList = document.querySelector('[data-loans-list]');
  const overviewApplications = document.querySelector('[data-overview-applications]');
  const overviewLoans = document.querySelector('[data-overview-loans]');
  const overviewPayment = document.querySelector('[data-overview-payment]');
  const profileForm = document.querySelector('#profileForm');
  const profileMessage = document.querySelector('[data-profile-message]');
  const profileEmailField = document.querySelector('[data-profile-email-field]');
  const loanDetail = document.querySelector('[data-loan-detail]');
  const loanDetailContent = document.querySelector('[data-loan-detail-content]');
  const loanListPanel = loanDetail?.previousElementSibling || null;
  let user = null;
  let loans = [];

  const syncProfileBank = () => {
    if (!profileForm) return;
    profileForm.elements.branch_code.value = profileSchema.bankBranchCode(profileForm.elements.bank_name.value);
  };
  const syncProfileAccountHolder = () => {
    if (!profileForm) return;
    profileForm.elements.bank_account_holder.value = [profileForm.elements.first_name.value, profileForm.elements.last_name.value].map(value => value.trim()).filter(Boolean).join(' ');
  };
  profileForm?.elements.bank_name?.addEventListener('change', syncProfileBank);
  profileForm?.elements.first_name?.addEventListener('input', syncProfileAccountHolder);
  profileForm?.elements.last_name?.addEventListener('input', syncProfileAccountHolder);

  const closeLoanDetail = () => {
    if (loanDetail) loanDetail.hidden = true;
    if (loanListPanel) loanListPanel.hidden = false;
  };

  const selectTab = name => {
    document.querySelectorAll('[data-account-section]').forEach(section => { section.hidden = section.dataset.accountSection !== name; });
    document.querySelectorAll('[data-account-nav]').forEach(button => button.classList.toggle('active', button.dataset.accountNav === name));
    if (name !== 'loans') closeLoanDetail();
  };

  document.querySelectorAll('[data-account-nav]').forEach(button => button.addEventListener('click', () => selectTab(button.dataset.accountNav)));

  const renderApplications = applications => {
    if (!applications.length) {
      applicationList.innerHTML = `<div class="portal-empty"><strong>No applications yet</strong><p>Your applications will appear here after you submit them.</p><a class="btn btn-primary" href="apply.html">Start application</a></div>`;
      return;
    }
    applicationList.innerHTML = applications.map(item => {
      const timing = item.preferred_collection_date
        ? `Collection ${date(item.preferred_collection_date)}`
        : `${escape(item.loan_term_months)} month${Number(item.loan_term_months) === 1 ? '' : 's'}`;
      return `
        <article class="portal-row">
          <div><span class="portal-kicker">${escape(item.reference)}</span><strong>${amount(item.loan_amount)}</strong><small>${timing} · Applied ${date(item.created_at)}</small></div>
          <span class="status-badge status-${escape(item.status)}">${escape(statusLabel(item.status))}</span>
        </article>`;
    }).join('');
  };

  const renderLoans = rows => {
    if (!rows.length) {
      loanList.innerHTML = `<div class="portal-empty"><strong>No loans yet</strong><p>Approved loans will appear here with balances, payments, transactions and documents.</p></div>`;
      return;
    }
    loanList.innerHTML = rows.map(item => `
      <article class="portal-row loan-row">
        <div><span class="portal-kicker">${escape(item.account_number || 'Loan account')}</span><strong>${amount(item.outstanding_balance)} outstanding</strong><small>Started ${date(item.start_date)} · Due ${date(item.due_date)}</small></div>
        <div class="portal-row-actions"><span class="status-badge status-${escape(item.status)}">${escape(statusLabel(item.status))}</span><button type="button" class="text-button" data-view-loan="${escape(item.id)}">View loan</button></div>
      </article>`).join('');
  };

  async function loadLoan(id) {
    const selected = loans.find(item => item.id === id);
    if (!selected) return;
    if (loanListPanel) loanListPanel.hidden = true;
    loanDetail.hidden = false;
    loanDetailContent.innerHTML = `<div class="portal-loading">Loading loan details…</div>`;

    const [{ data: transactions, error: txError }, { data: documents, error: docError }] = await Promise.all([
      client.from('loan_transactions').select('id,transaction_date,description,amount,transaction_type').eq('user_id', user.id).eq('loan_id', id).order('transaction_date', { ascending: false }),
      client.from('loan_documents').select('id,title,document_type,storage_path,storage_bucket,created_at').eq('user_id', user.id).eq('loan_id', id).order('created_at', { ascending: false })
    ]);

    const tx = txError ? [] : (transactions || []);
    const docs = docError ? [] : (documents || []);
    loanDetailContent.innerHTML = `
      <div class="loan-detail-head">
        <div><span class="eyebrow">${escape(selected.account_number || 'Loan')}</span><h2>${amount(selected.outstanding_balance)}</h2><p>Outstanding balance</p></div>
        <span class="status-badge status-${escape(selected.status)}">${escape(statusLabel(selected.status))}</span>
      </div>
      <div class="loan-stat-grid">
        <div><span>Original amount</span><strong>${amount(selected.principal_amount)}</strong></div>
        <div><span>Term</span><strong>${escape(selected.term_months)} months</strong></div>
        <div><span>Next payment</span><strong>${selected.next_payment_amount == null ? '—' : amount(selected.next_payment_amount)}</strong><small>${date(selected.next_payment_date)}</small></div>
        <div><span>Due date</span><strong>${date(selected.due_date)}</strong></div>
      </div>
