    if (loadProfile && !profileLoaded) {
      profileLoaded = true;
      const [{ data: profile }, { data: applications }] = await Promise.all([
        supabaseClient.from('customer_profiles').select('*').eq('id', currentUser.id).maybeSingle(),
        supabaseClient.from('loan_applications').select('*').eq('user_id', currentUser.id).order('created_at', { ascending: false }).limit(1)
      ]);
      latestApplication = applications?.[0] || null;
      let used = false;
      used = prefillFromSource(latestApplication) || used;
      used = prefillFromSource(profile) || used;
      used = fillIfBlank('firstName', currentUser.user_metadata?.first_name || '') || used;
      used = fillIfBlank('lastName', currentUser.user_metadata?.last_name || '') || used;
      if (used) profileNotes.forEach(note => { note.hidden = false; });
      await loadReusableDocuments();
      updateDependantsUI();
      updateEmploymentUI();
      updateEmploymentDuration();
      updatePayUI();
      syncBankBranchCode();
      syncAccountHolder();
      updateIdDerived();
      updateAffordability();
    }
    updateSubmitVisibility();
    return currentUser;
  }

  function setStep(step) {
    currentStep = Math.min(steps.length, Math.max(1, Number(step)));
    steps.forEach(section => section.classList.toggle('active', Number(section.dataset.step) === currentStep));
    navItems.forEach(item => {
      const number = Number(item.dataset.stepNav);
      item.classList.toggle('active', number === currentStep);
      item.classList.toggle('done', number < currentStep);
    });
    progressText.textContent = `Step ${currentStep} of ${steps.length}`;
    progressBar.style.width = `${(currentStep / steps.length) * 100}%`;
    prevBtn.disabled = currentStep === 1;
    nextBtn.hidden = currentStep === steps.length;
    submitBtn.hidden = true;
    showAlert('');
    if (currentStep === 4) updateAffordability();
    if (currentStep === 5) syncAccountHolder(true);
    if (currentStep === 6) buildReview();
    updateSubmitVisibility();
    window.scrollTo({ top: Math.max(0, document.querySelector('.application-main').offsetTop - 85), behavior: 'smooth' });
  }

  function updateLoan() {
    const amount = Number(amountInput.value);
    const term = Number(termInput.value);
    amountText.textContent = money(amount);
    termText.textContent = `${term} month${term === 1 ? '' : 's'}`;
    try { localStorage.setItem(PLAN_KEY, JSON.stringify({ amount, term })); } catch (_) {}
  }

  function validateField(field) {
    if (!field || field.disabled || field.type === 'hidden') return true;
    const wrapper = field.closest('.field');
    const error = wrapper?.querySelector('.field-error');
    let message = '';

    if (field.type === 'file') {
      const type = Object.keys(documentInputs).find(key => documentInputs[key] === field.name);
      if (reusableDocs[type]) return true;
      const file = field.files?.[0];
      if (field.required && !file) message = 'Please upload this document.';
      if (file) {
        if (!allowedFileTypes.has(file.type)) message = 'Use a PDF, JPG or PNG file.';
        if (file.size > 6 * 1024 * 1024) message = 'This file is larger than 6 MB.';
      }
    } else if (!field.checkValidity()) {
      if (field.validity.valueMissing) message = field.type === 'checkbox' ? 'Please confirm this before submitting.' : 'This field is required.';
      else if (field.validity.typeMismatch) message = 'Please enter a valid value.';
      else if (field.validity.tooShort) message = 'This value is too short.';
      else if (field.validity.rangeUnderflow) message = 'Enter a valid value.';
      else if (field.validity.rangeOverflow) message = 'Enter a valid value.';
      else message = 'Please check this field.';
    }

    if (field.name === 'idNumber' && field.value && !parseSouthAfricanId(field.value)) message = 'Enter a valid South African ID number for an applicant aged 18 or older.';
    if (field.name === 'email' && field.value && !/^\S+@\S+\.\S+$/.test(field.value.trim())) message = 'Enter a valid email address.';
    if (field.name === 'mobile' && field.value) {
      const digits = field.value.replace(/\D/g, '');
      if (digits.length < 9 || digits.length > 12) message = 'Enter a valid mobile number.';
    }

    if (wrapper) wrapper.classList.toggle('invalid', Boolean(message));
    if (error) error.textContent = message;
    if (field.type === 'file') field.closest('.upload-card')?.classList.toggle('invalid', Boolean(message));
    return !message;
  }

  function validateStep(stepNumber) {
    const section = form.querySelector(`[data-step="${stepNumber}"]`);
    const fields = [...section.querySelectorAll('input,select,textarea')].filter(el => el.name !== 'website' && !el.disabled);
    let valid = true;
    fields.forEach(field => { if (!validateField(field)) valid = false; });
    if (stepNumber === 5) {
      syncBankBranchCode();
      if (!branchCode.value) valid = false;
      Object.keys(documentInputs).forEach(type => { if (!documentComplete(type)) valid = false; });
    }
    if (!valid) {
      showAlert('Please check the highlighted information before continuing.');
      const firstInvalid = section.querySelector('.invalid input,.invalid select,.invalid textarea,input:invalid,select:invalid');
      firstInvalid?.focus({ preventScroll: true });
      firstInvalid?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
    return valid;
  }

  function documentReviewValue(type) {
    if (reusableDocs[type]) return 'Verified document on file';
    const field = form.elements[documentInputs[type]];
    return field?.files?.[0]?.name || 'Not selected';
  }

  const reviewSections = [
    { title: 'Loan request', step: 1, fields: [['Amount', 'loanAmount', 'money'], ['Term', 'loanTerm', 'term']] },
    { title: 'Personal details', step: 2, fields: [['Name', ['firstName','lastName'], 'join'], ['ID number', 'idNumber', 'maskId'], ['Date of birth', 'idNumber', 'dob'], ['Mobile', 'mobile'], ['Email', 'email'], ['Province', 'province'], ['Address', 'address']] },
    { title: 'Work & income', step: 3, fields: [['Income source', 'employmentStatus'], ['Employer / source', 'employerName'], ['Occupation', 'jobTitle'], ['Started', 'employmentStartDate', 'month'], ['Net monthly income', 'monthlyIncome', 'money'], ['Pay frequency', 'payFrequency'], ['Next pay date', 'nextPayDate', 'date']] },
    { title: 'Affordability', step: 4, fields: [['Rent / bond', 'housingExpense', 'money'], ['Groceries', 'foodExpense', 'money'], ['Transport', 'transportExpense', 'money'], ['Utilities', 'utilitiesExpense', 'money'], ['Insurance / medical', 'insuranceExpense', 'money'], ['Existing credit', 'debtExpense', 'money'], ['Other', 'otherExpense', 'money']] },
    { title: 'Bank & documents', step: 5, fields: [['Bank', 'bankName'], ['Account type', 'accountType'], ['Account holder', 'accountHolder'], ['Account number', 'accountNumber', 'maskAccount'], ['ID document', 'id_document', 'document'], ['Proof of income', 'proof_of_income', 'document'], ['Bank statement', 'bank_statement', 'document']] }
  ];

  function valueFor(spec, format) {
    if (Array.isArray(spec)) return spec.map(name => form.elements[name]?.value || '').filter(Boolean).join(' ');
    const field = form.elements[spec];
    const val = field?.value || '';
    if (format === 'money') return money(val);
    if (format === 'term') return `${val} month${Number(val) === 1 ? '' : 's'}`;
    if (format === 'maskId') return val ? `•••••••••${val.slice(-4)}` : '';
    if (format === 'maskAccount') return val ? `••••${val.slice(-4)}` : '';
    if (format === 'month') {
      if (!val) return '';
      const date = new Date(`${val}-01T00:00:00`);
      return Number.isNaN(date.getTime()) ? val : monthFormatter.format(date);
    }
    if (format === 'date') return val ? dateFormatter.format(new Date(`${val}T00:00:00`)) : '';
    if (format === 'dob') return idInfo ? dateFormatter.format(idInfo.dob) : '';
    if (format === 'document') return documentReviewValue(spec);
    return val;
  }

  function buildReview() {
    updateIdDerived();
    reviewSummary.innerHTML = reviewSections.map(section => {
      const items = section.fields.filter(([, field]) => field !== 'jobTitle' || !jobTitle?.disabled).map(([label, field, format]) => `<div class="review-item"><span>${escapeHTML(label)}</span><strong>${escapeHTML(valueFor(field, format) || '—')}</strong></div>`).join('');
      return `<section class="review-section"><div class="review-section-head"><strong>${escapeHTML(section.title)}</strong><button type="button" data-go-step="${section.step}">Edit</button></div><div class="review-grid">${items}</div></section>`;
    }).join('');
  }

  function saveDraft() {
    const draft = {};
    [...form.elements].forEach(field => {
      if (!field.name || field.type === 'file' || sensitiveFields.has(field.name)) return;
      if (field.type === 'checkbox' || field.type === 'radio') draft[field.name] = field.checked ? field.value : '';
      else draft[field.name] = field.value;
    });
    draft._step = Math.min(currentStep, 5);
    draft._savedAt = Date.now();
    try { localStorage.setItem(DRAFT_KEY, JSON.stringify(draft)); } catch (_) {}
  }

  function restoreDraft() {
    let draft = null;
    let plan = null;
    try {
      draft = JSON.parse(localStorage.getItem(DRAFT_KEY) || 'null');
      plan = JSON.parse(localStorage.getItem(PLAN_KEY) || 'null');
    } catch (_) {}
    if (plan?.amount) amountInput.value = String(plan.amount);
    if (plan?.term) termInput.value = String(plan.term);
    if (draft && Date.now() - Number(draft._savedAt || 0) < 7 * 24 * 60 * 60 * 1000) {
      Object.entries(draft).forEach(([name, val]) => {
        if (name.startsWith('_') || sensitiveFields.has(name)) return;
        const field = form.elements[name];
        if (!field || field.type === 'file') return;
        if (field.type === 'checkbox' || field.type === 'radio') field.checked = field.value === val;
        else field.value = val;
      });
      currentStep = Math.max(1, Math.min(5, Number(draft._step || 1)));
    }
    updateDependantsUI();
    updateEmploymentUI();
    updateEmploymentDuration();
    updatePayUI();
    syncBankBranchCode();
    syncAccountHolder();
    updateIdDerived();
    updateLoan();
    updateAffordability();
    setStep(currentStep);
  }

  function fileExtension(file) {
    const fromName = String(file.name || '').split('.').pop()?.toLowerCase();
    if (['pdf','jpg','jpeg','png'].includes(fromName)) return fromName === 'jpeg' ? 'jpg' : fromName;
    if (file.type === 'application/pdf') return 'pdf';
    if (file.type === 'image/png') return 'png';
    return 'jpg';
  }

  async function uploadDocument(applicationId, documentType, file) {
    const slug = documentType.replaceAll('_', '-');
    const path = `${currentUser.id}/${applicationId}/${slug}.${fileExtension(file)}`;
    const { error } = await supabaseClient.storage.from('application-documents').upload(path, file, { upsert: false, contentType: file.type, cacheControl: '3600' });
    if (error) throw new Error(`We could not upload your ${documentTitles[documentType].toLowerCase()}. Please try again.`);
    return path;
  }

  function createReference(applicationId) {
    const day = new Date().toISOString().slice(0, 10).replaceAll('-', '');
    return `KR-${day}-${applicationId.replaceAll('-', '').slice(0, 8).toUpperCase()}`;
  }

  function affordabilityNumbers() {
    const income = number('monthlyIncome');
    const expenses = expenseNames.reduce((sum, name) => sum + number(name), 0);
    return { expenses, disposable: income - expenses, ratio: income > 0 ? expenses / income : 0 };
  }

  function applicationRecord(applicationId, reference, documentPaths) {
    const affordability = affordabilityNumbers();
    const parsedId = parseSouthAfricanId(value('idNumber'));
    return {
      id: applicationId,
      user_id: currentUser.id,
      reference,
      status: 'received',
      source: 'website',
      loan_amount: number('loanAmount'),
      loan_term_months: number('loanTerm'),
      first_name: value('firstName').trim(),
      last_name: value('lastName').trim(),
      id_number: value('idNumber').trim(),
      date_of_birth: parsedId?.iso || null,
      age_at_application: parsedId?.age || null,
      mobile: value('mobile').trim(),
      email: currentUser.email?.trim().toLowerCase() || value('email').trim().toLowerCase(),
      marital_status: value('maritalStatus'),
      dependants: number('dependants'),
      province: value('province'),
      residential_address: value('address').trim(),
      employment_status: value('employmentStatus'),
      income_source_name: value('employerName').trim(),
      job_title: jobTitle?.disabled ? 'Not applicable' : value('jobTitle').trim(),
      employment_start_month: `${value('employmentStartDate')}-01`,
      net_monthly_income: number('monthlyIncome'),
      pay_frequency: value('payFrequency'),
      pay_day: value('payDay') ? number('payDay') : null,
      next_pay_date: value('nextPayDate'),
      income_source_phone: null,
      housing_expense: number('housingExpense'),
      food_expense: number('foodExpense'),
      transport_expense: number('transportExpense'),
      utilities_expense: number('utilitiesExpense'),
      insurance_expense: number('insuranceExpense'),
      dependant_expense: number('dependantExpense'),
      debt_expense: number('debtExpense'),
      other_expense: number('otherExpense'),
      total_monthly_expenses: affordability.expenses,
      disposable_income: affordability.disposable,
      expense_to_income_ratio: affordability.ratio,
      bank_name: value('bankName'),
      bank_account_type: value('accountType'),
      bank_account_holder: value('accountHolder').trim(),
      bank_account_number: value('accountNumber').trim(),
      branch_code: value('branchCode').trim(),
      id_document_path: documentPaths.id_document,
      income_document_path: documentPaths.proof_of_income,
      bank_statement_path: documentPaths.bank_statement,
      accuracy_consent: Boolean(form.elements.accuracyConsent?.checked),
      processing_consent: Boolean(form.elements.processingConsent?.checked),
      application_consent: Boolean(form.elements.applicationConsent?.checked),
      marketing_consent: Boolean(form.elements.marketingConsent?.checked)
    };
  }

  function profileRecord() {
    return {
      id: currentUser.id,
      first_name: value('firstName').trim(),
      last_name: value('lastName').trim(),
      id_number: value('idNumber').trim(),
      mobile: value('mobile').trim(),
      marital_status: value('maritalStatus'),
      dependants: number('dependants'),
      province: value('province'),
      residential_address: value('address').trim(),
      employment_status: value('employmentStatus'),
      income_source_name: value('employerName').trim(),
      job_title: jobTitle?.disabled ? 'Not applicable' : value('jobTitle').trim(),
      employment_start_month: `${value('employmentStartDate')}-01`,
      net_monthly_income: number('monthlyIncome'),
      pay_frequency: value('payFrequency'),
      pay_day: value('payDay') ? number('payDay') : null,
      income_source_phone: null,
      housing_expense: number('housingExpense'),
      food_expense: number('foodExpense'),
      transport_expense: number('transportExpense'),
      utilities_expense: number('utilitiesExpense'),
      insurance_expense: number('insuranceExpense'),
      dependant_expense: number('dependantExpense'),
      debt_expense: number('debtExpense'),
      other_expense: number('otherExpense'),
      bank_name: value('bankName'),
      bank_account_type: value('accountType'),
      bank_account_holder: value('accountHolder').trim(),
      bank_account_number: value('accountNumber').trim(),
      branch_code: value('branchCode').trim(),
      last_application_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };
  }

  async function resolveDocumentPaths(applicationId) {
    const paths = {};
    const newDocuments = [];
    for (const type of Object.keys(documentInputs)) {
      if (reusableDocs[type]) {
        paths[type] = reusableDocs[type].storage_path;
        continue;
      }
      const input = form.elements[documentInputs[type]];
      const file = input.files[0];
      const path = await uploadDocument(applicationId, type, file);
      paths[type] = path;
      newDocuments.push({
        user_id: currentUser.id,
        source_application_id: applicationId,
        document_type: type,
        title: documentTitles[type],
        storage_bucket: 'application-documents',
        storage_path: path,
        verification_status: 'pending'
      });
    }
    return { paths, newDocuments };
  }

  nextBtn.addEventListener('click', async () => {
    if (!validateStep(currentStep)) return;
    if (currentStep === 1 && !(await refreshCurrentUser(true))) {
      saveDraft();
      if (authGate) {
        authGate.hidden = false;
        authGate.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
      return;
    }
    saveDraft();
    setStep(currentStep + 1);
  });

  prevBtn.addEventListener('click', () => { saveDraft(); setStep(currentStep - 1); });

  reviewSummary.addEventListener('click', event => {
    const button = event.target.closest('[data-go-step]');
    if (button) setStep(Number(button.dataset.goStep));
  });

  form.addEventListener('click', event => {
    const button = event.target.closest('[data-upload-new]');
    if (button) stopReusingDocument(button.dataset.uploadNew);
  });

  [amountInput, termInput].forEach(input => input.addEventListener('input', () => { updateLoan(); saveDraft(); updateSubmitVisibility(); }));
  incomeInput?.addEventListener('input', updateAffordability);
  form.querySelectorAll('.affordability-fields input').forEach(input => input.addEventListener('input', updateAffordability));
  bankSelect?.addEventListener('change', () => { syncBankBranchCode(); updateSubmitVisibility(); });
  idNumber?.addEventListener('input', () => { updateIdDerived(); updateSubmitVisibility(); });
  hasDependants?.addEventListener('change', () => { updateDependantsUI(); updateSubmitVisibility(); });
  employmentStatus?.addEventListener('change', () => { updateEmploymentUI(); updateSubmitVisibility(); });
  employmentStartDate?.addEventListener('change', updateEmploymentDuration);
  payFrequency?.addEventListener('change', () => { updatePayUI(); updateSubmitVisibility(); });
  payDay?.addEventListener('input', () => { deriveMonthlyNextPayDate(); updateSubmitVisibility(); });
  form.elements.firstName?.addEventListener('input', () => syncAccountHolder(true));
  form.elements.lastName?.addEventListener('input', () => syncAccountHolder(true));

  form.addEventListener('input', event => {
    const field = event.target;
    if (field.matches('input,select,textarea') && field.type !== 'file') {
      if (field.closest('.field')?.classList.contains('invalid')) validateField(field);
      window.clearTimeout(form._draftTimer);
      form._draftTimer = window.setTimeout(saveDraft, 350);
      updateSubmitVisibility();
    }
  });
  form.addEventListener('change', updateSubmitVisibility);

  form.querySelectorAll('input[type="file"]').forEach(input => {
    input.addEventListener('change', () => {
      const file = input.files?.[0];
      const label = form.querySelector(`[data-file-name="${input.name}"]`);
      if (label) label.textContent = file ? `${file.name} · ${(file.size / 1024 / 1024).toFixed(1)} MB` : 'Choose file';
      input.closest('.upload-card')?.classList.toggle('has-file', Boolean(file));
      validateField(input);
      updateSubmitVisibility();
    });
  });

  form.addEventListener('submit', async event => {
    event.preventDefault();
    const user = await refreshCurrentUser(false);
    if (!user) {
      showAlert('Your login session has ended. Sign in again before submitting.');
      submitBtn.hidden = true;
      return;
    }

    updatePayUI();
    updateIdDerived();
    for (let step = 1; step <= steps.length; step += 1) {
      if (!validateStep(step)) { setStep(step); return; }
    }
    if (!applicationIsComplete()) {
      updateSubmitVisibility();
      showAlert('Please complete every required field, document and confirmation before submitting.');
      return;
    }

    const { data: pendingApps } = await supabaseClient
      .from('loan_applications')
      .select('id,status')
      .eq('user_id', user.id)
      .in('status', ['received', 'under_review']);
    if ((pendingApps || []).length) {
      showAlert('You already have an application awaiting review. Please wait for a decision before submitting another one.');
      return;
    }

    showAlert('');
    submitBtn.classList.add('loading');
    submitBtn.disabled = true;
    submitLabel.textContent = 'Sending application';

    try {
      const applicationId = crypto.randomUUID();
      const reference = createReference(applicationId);
      const { paths, newDocuments } = await resolveDocumentPaths(applicationId);

      const { error } = await supabaseClient.from('loan_applications').insert(applicationRecord(applicationId, reference, paths));
      if (error) throw new Error('We could not save your application right now. Please try again.');

      if (newDocuments.length) {
        const { error: docError } = await supabaseClient.from('customer_documents').insert(newDocuments);
        if (docError) console.warn('Application saved, but document tracking could not be created.', docError);
      }

      const { error: profileError } = await supabaseClient.from('customer_profiles').upsert(profileRecord());
      if (profileError) console.warn('Application saved, but profile reuse data could not be refreshed.', profileError);

      try { localStorage.removeItem(DRAFT_KEY); localStorage.removeItem(PLAN_KEY); } catch (_) {}
      window.location.href = `application-received.html?ref=${encodeURIComponent(reference)}`;
    } catch (error) {
      showAlert(error.message || 'We could not send your application right now. Please try again.');
      submitBtn.classList.remove('loading');
      submitBtn.disabled = false;
      submitLabel.textContent = 'Submit application';
      updateSubmitVisibility();
    }
  });

  async function init() {
    restoreDraft();
    await refreshCurrentUser(true);
    updateDependantsUI();
    updateEmploymentUI();
    updateEmploymentDuration();
    updatePayUI();
    syncBankBranchCode();
    syncAccountHolder();
    updateIdDerived();
    updateAffordability();
    updateSubmitVisibility();
  }

  init();
})();

(() => {
  if (window.kredrunSupabase) return;

  const config = window.KREDRUN_SUPABASE;
  if (!window.supabase || !config?.url || !config?.publishableKey) {
    console.error('KredRun authentication is not configured.');
    return;
  }

  const REQUEST_TIMEOUT_MS = 20000;
  const boundedFetch = (input, init = {}) => {
    const controller = new AbortController();
    const upstream = init.signal;
    const relayAbort = () => controller.abort(upstream?.reason);
    if (upstream) {
      if (upstream.aborted) relayAbort();
      else upstream.addEventListener('abort', relayAbort, { once: true });
    }
    const timer = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    return fetch(input, { ...init, signal: controller.signal }).finally(() => {
      window.clearTimeout(timer);
      upstream?.removeEventListener?.('abort', relayAbort);
    });
  };

  const client = window.supabase.createClient(config.url, config.publishableKey, {
    auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true, flowType: 'pkce' },
    global: { fetch: boundedFetch }
  });

  const isInternalEmail = value => /^kr-[a-f0-9]+@login\.invalid$/i.test(String(value || '').trim());
  const cleanContactEmail = value => {
    const email = String(value || '').trim().toLowerCase();
    return /^\S+@\S+\.\S+$/.test(email) && !isInternalEmail(email) ? email : '';
  };
  const readLoanPlan = () => {
    try { return JSON.parse(localStorage.getItem('kredrun-loan-plan') || 'null'); }
    catch (_) { return null; }
  };

  // Older phone-first accounts used an internal placeholder email. Never expose that value to customer-facing code.
  const rawGetUser = client.auth.getUser.bind(client.auth);
  client.auth.getUser = async (...args) => {
    const result = await rawGetUser(...args);
    const user = result?.data?.user;
    if (user && isInternalEmail(user.email)) result.data.user = { ...user, email: null };
    return result;
  };

  // Attach calculator data and the real customer email whenever application/profile data is saved.
  const rawFrom = client.from.bind(client);
  client.from = relation => {
    const builder = rawFrom(relation);

    if (relation === 'loan_applications' && typeof builder.insert === 'function') {
      const rawInsert = builder.insert.bind(builder);
      builder.insert = (values, options) => {
        const collectionDate = readLoanPlan()?.collectionDate || null;
        const email = cleanContactEmail(document.querySelector('#loanApplication [name="email"]')?.value);
        const patch = row => row && typeof row === 'object' && !Array.isArray(row)
          ? { ...row, preferred_collection_date: collectionDate || row.preferred_collection_date || null, email: email || (isInternalEmail(row.email) ? null : row.email) }
          : row;
        const payload = Array.isArray(values) ? values.map(patch) : patch(values);
        return rawInsert(payload, options);
      };
    }

    if (relation === 'customer_profiles' && typeof builder.upsert === 'function') {
      const rawUpsert = builder.upsert.bind(builder);
      builder.upsert = (values, options) => {
        const email = cleanContactEmail(document.querySelector('#loanApplication [name="email"]')?.value);
        const patch = row => row && typeof row === 'object' && !Array.isArray(row) && email ? { ...row, email } : row;
        const payload = Array.isArray(values) ? values.map(patch) : patch(values);
        return rawUpsert(payload, options);
      };
    }

    return builder;
  };

  const safeNext = (value, fallback = 'account.html') => {
    if (!value) return fallback;
    try {
      const parsed = new URL(value, window.location.origin);
      if (parsed.origin !== window.location.origin) return fallback;
      const file = parsed.pathname.split('/').pop() || fallback;
      if (!/^[a-z0-9._-]+\.html$/i.test(file)) return fallback;
      return `${file}${parsed.search}${parsed.hash}`;
    } catch (_) { return fallback; }
  };

  const validSaId = value => {
    const id = String(value || '').replace(/\D/g, '');
    if (!/^\d{13}$/.test(id)) return false;
    let odd = 0;
    for (let i = 0; i < 12; i += 2) odd += Number(id[i]);
    const evens = id.slice(1, 12).split('').filter((_, i) => i % 2 === 0).join('');
    const even = [...String(Number(evens || 0) * 2)].reduce((sum, d) => sum + Number(d), 0);
    return ((10 - ((odd + even) % 10)) % 10) === Number(id[12]);
  };

  const identityRequest = async (payload, token = '') => {
    const headers = { 'Content-Type': 'application/json', apikey: config.publishableKey };
    if (token) headers.Authorization = `Bearer ${token}`;
    let response;
    try {
      response = await boundedFetch(`${config.url}/functions/v1/identity-auth`, {
        method: 'POST', headers, body: JSON.stringify(payload)
      });
    } catch (error) {
      if (error?.name === 'AbortError') throw new Error('The request took too long. Please try again.');
      throw error;
    }
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data?.error || 'We could not complete that request.');
    return data;
  };

  const completePendingProfile = async () => {
    const { data } = await client.auth.getSession();
    const token = data?.session?.access_token;
    if (!token) return null;
    try { return await identityRequest({ action: 'complete_profile' }, token); }
    catch (_) { return null; }
  };

  let cachedAccessToken = '';
  let cachedUserPromise = null;
  const getCurrentUser = async () => {
    const { data } = await client.auth.getSession();
    const accessToken = data?.session?.access_token || '';
    if (!accessToken) {
      cachedAccessToken = '';
      cachedUserPromise = null;
      return null;
    }
    if (accessToken !== cachedAccessToken || !cachedUserPromise) {
      cachedAccessToken = accessToken;
      cachedUserPromise = client.auth.getUser()
        .then(({ data: userData, error }) => error ? null : (userData?.user || null))
        .catch(() => null);
    }
    return cachedUserPromise;
  };

  window.kredrunSupabase = client;
  window.KredRunAuth = {
    client, safeNext, validSaId, identityRequest, completePendingProfile, isInternalEmail,
    getUser: getCurrentUser,
    async requireUser(next = 'account.html') {
      const user = await this.getUser();
      if (!user) {
        window.location.href = `login.html?next=${encodeURIComponent(safeNext(next))}`;
        return null;
      }
      return user;
    }
  };

  const gate = document.querySelector('[data-auth-gate]');
  if (gate) {
    gate.innerHTML = '<strong>Continue to your application</strong><span>Your session has ended.</span><div class="auth-gate-actions"><a class="btn btn-primary" href="login.html?next=apply.html">Continue</a></div>';
  }

  const setupSmartApplication = async () => {
    if (!document.body.classList.contains('application-page') || document.body.classList.contains('received-body')) return;

    document.body.classList.add('smart-application', 'auth-checking');

    const plan = readLoanPlan();
    if (!plan?.amount || !plan?.collectionDate) {
      location.replace('index.html#loan-calculator');
      return;
    }

    const nativeScrollTo = window.scrollTo.bind(window);
    window.scrollTo = (first, second) => {
      if (typeof first === 'object' && first?.behavior === 'smooth') return;
      return nativeScrollTo(first, second);
    };

    const user = await getCurrentUser();
    if (!user) {
      const next = `${location.pathname.split('/').pop() || 'apply.html'}${location.search}${location.hash}`;
      location.replace(`login.html?next=${encodeURIComponent(safeNext(next, 'apply.html'))}`);
      return;
    }

    document.body.classList.remove('auth-checking');

    const money = value => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR', maximumFractionDigits: 0 }).format(Number(value || 0)).replace('ZAR', 'R').trim();
    const dateText = value => {
      if (!value) return '';
      const date = new Date(`${value}T00:00:00`);
      return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat('en-ZA', { day: '2-digit', month:'short', year:'numeric' }).format(date);
    };

    const addPlanChip = () => {
      if (document.querySelector('[data-smart-plan-chip]')) return;
      const progressCard = document.querySelector('.progress-card');
      if (!progressCard) return;
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'smart-plan-chip';
      chip.dataset.smartPlanChip = '';
      chip.innerHTML = `<span>Loan</span><strong>${money(plan.amount)} · ${dateText(plan.collectionDate)}</strong><em>Change</em>`;
      chip.addEventListener('click', () => { window.location.href = 'index.html#loan-calculator'; });
      progressCard.appendChild(chip);
    };

    const syncReviewCollectionDate = () => {
      const review = document.querySelector('#reviewSummary');
      if (!review) return;
      const loanSection = review.querySelector('.review-section');
      if (!loanSection) return;
      const items = [...loanSection.querySelectorAll('.review-item')];
      const termItem = items.find(item => item.querySelector('span')?.textContent?.trim() === 'Term' || item.querySelector('span')?.textContent?.trim() === 'Collection date');
      if (!termItem) return;
      const label = termItem.querySelector('span');
      const value = termItem.querySelector('strong');
      const nextLabel = 'Collection date';
      const nextValue = dateText(plan.collectionDate);
      // Only touch the DOM when the value actually changed. Rewriting observed text here
      // used to retrigger this MutationObserver forever and could freeze the browser.
      if (label && label.textContent !== nextLabel) label.textContent = nextLabel;
      if (value && value.textContent !== nextValue) value.textContent = nextValue;
    };

    const review = document.querySelector('#reviewSummary');
    if (review) {
      new MutationObserver(syncReviewCollectionDate).observe(review, { childList: true, subtree: true });
      syncReviewCollectionDate();
    }

    const collapseIdentity = () => {
      const section = document.querySelector('#loanApplication [data-step="2"]');
      if (!section || section.querySelector('[data-smart-identity]')) return false;
      const fields = ['firstName', 'lastName', 'idNumber', 'mobile'].map(name => document.querySelector(`#loanApplication [name="${name}"]`));
      if (fields.some(field => !field || !String(field.value || '').trim())) return false;

      const [firstName, lastName, idNumber, mobile] = fields.map(field => String(field.value || '').trim());
      const grid = section.querySelector('.form-grid');
      if (!grid) return false;

      const summary = document.createElement('div');
      summary.className = 'smart-identity-summary';
      summary.dataset.smartIdentity = '';
      summary.innerHTML = `<div><span>Your details</span><strong>${firstName} ${lastName}</strong><small>ID •••••••••${idNumber.slice(-4)} · ${mobile}</small></div><button type="button">Change</button>`;
      summary.querySelector('button').addEventListener('click', () => {
        section.classList.toggle('show-identity-fields');
        summary.querySelector('button').textContent = section.classList.contains('show-identity-fields') ? 'Done' : 'Change';
      });
      grid.parentNode.insertBefore(summary, grid);
      fields.forEach(field => field.closest('.field')?.classList.add('smart-identity-field'));
      section.classList.add('identity-collapsed');
      section.querySelectorAll('[data-profile-prefill]').forEach(note => { note.hidden = true; });
      return true;
    };

    let tries = 0;
    const timer = window.setInterval(() => {
      tries += 1;
      addPlanChip();
      const collapsed = collapseIdentity();
      syncReviewCollectionDate();
      if (tries > 20 || collapsed) window.clearInterval(timer);
    }, 180);

    window.setTimeout(() => {
      const firstStep = document.querySelector('#loanApplication [data-step="1"]');
      const next = document.querySelector('#loanApplication [data-next]');
      if (firstStep?.classList.contains('active') && next) next.click();
    }, 220);
  };

  setupSmartApplication();
})();

(() => {
  const auth = window.KredRunAuth;
  const client = window.kredrunSupabase;
  if (!auth || !client) return;

  const params = new URLSearchParams(location.search);
  const next = auth.safeNext(params.get('next'), 'account.html');
  const root = document.querySelector('[data-login-identity-auth]');
  const pageFeedback = document.querySelector('[data-auth-feedback]');

  const setLoading = (button, loading, label) => {
    if (!button) return;
    button.disabled = loading;
    if (!button.dataset.label) button.dataset.label = button.textContent;
    button.textContent = loading ? label : button.dataset.label;
  };

  const setSession = async session => {
    if (!session?.access_token || !session?.refresh_token) throw new Error('We could not continue. Please try again.');
    const { error } = await client.auth.setSession({ access_token: session.access_token, refresh_token: session.refresh_token });
    if (error) throw error;
    await auth.completePendingProfile();
    location.href = next;
  };

  if (root) {
    root.innerHTML = `
      <div class="auth-feedback" data-feedback role="status" aria-live="polite"></div>

      <section data-step="id">
        <form data-id-form>
          <div class="auth-field">
            <label>South African ID number</label>
            <input name="idNumber" inputmode="numeric" autocomplete="off" maxlength="13" pattern="[0-9]{13}" placeholder="13 digits" required autofocus>
          </div>
          <button class="btn btn-primary btn-wide" type="submit">Continue</button>
        </form>
      </section>

      <section data-step="new" hidden>
        <button class="auth-link identity-back" type="button" data-back-id>← Change ID number</button>
        <h2>Your details</h2>
        <form data-new-form>
          <div class="auth-name-grid">
            <div class="auth-field"><label>First name</label><input name="firstName" autocomplete="given-name" maxlength="80" required></div>
            <div class="auth-field"><label>Surname</label><input name="lastName" autocomplete="family-name" maxlength="80" required></div>
          </div>
          <div class="auth-field"><label>Cellphone number</label><input name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="082 123 4567" required></div>
          <div class="auth-field"><label>Password</label><input name="password" type="password" autocomplete="new-password" minlength="8" required><small>At least 8 characters.</small></div>
          <button class="btn btn-primary btn-wide" type="submit">Continue application</button>
        </form>
      </section>

      <section data-step="code" hidden>
        <button class="auth-link identity-back" type="button" data-back-id>← Change ID number</button>
        <h2>Enter the code</h2>
        <p class="auth-step-copy">Sent to <strong data-masked>your cellphone</strong>.</p>
        <form data-code-form>
          <div class="auth-field">
            <label>Verification code</label>
            <input name="token" class="identity-otp" inputmode="numeric" autocomplete="one-time-code" maxlength="8" placeholder="000000" required>
          </div>
          <button class="btn btn-primary btn-wide" type="submit">Continue application</button>
        </form>
        <div class="identity-code-links">
          <button class="auth-link" type="button" data-resend>Send a new code</button>
          <button class="auth-link" type="button" data-use-password>Use password instead</button>
        </div>
      </section>

      <section data-step="password" hidden>
        <button class="auth-link identity-back" type="button" data-back-id>← Change ID number</button>
        <h2>Enter your password</h2>
        <form data-password-form>
          <div class="auth-field"><label>Password</label><input name="password" type="password" autocomplete="current-password" minlength="8" required autofocus></div>
          <button class="btn btn-primary btn-wide" type="submit">Continue application</button>
        </form>
        <button class="auth-link identity-resend" type="button" data-use-code>Use a one-time code instead</button>
      </section>`;

    if (!document.querySelector('#identity-login-style')) {
      const style = document.createElement('style');
      style.id = 'identity-login-style';
      style.textContent = `
        [data-login-identity-auth] h2{margin:0 0 7px;font-size:1.35rem;letter-spacing:-.02em}
        .auth-step-copy{margin:0 0 18px;color:#6f7f89}
        .auth-name-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
        .identity-back{margin-bottom:16px}
        .identity-resend{display:block;margin:16px auto 0;text-align:center}
        .identity-otp{font-size:1.45rem!important;letter-spacing:.30em;text-align:center;font-weight:750}
        .identity-code-links{display:flex;justify-content:center;gap:20px;flex-wrap:wrap;margin-top:16px}
        .auth-field small{color:#778692;font-size:.78rem}
        @media(max-width:520px){.auth-name-grid{grid-template-columns:1fr}}
      `;
      document.head.appendChild(style);
    }

    const feedback = root.querySelector('[data-feedback]');
    const steps = [...root.querySelectorAll('[data-step]')];
    const idForm = root.querySelector('[data-id-form]');
    const newForm = root.querySelector('[data-new-form]');
    const codeForm = root.querySelector('[data-code-form]');
    const passwordForm = root.querySelector('[data-password-form]');
    const masked = root.querySelector('[data-masked]');
    const state = {
      idNumber: String(params.get('id') || '').replace(/\D/g, '').slice(0, 13),
      status: '',
      channel: '',
      methods: [],
      preferPassword: params.get('mode') === 'password'
    };

    const show = (message = '', type = 'error') => {
      feedback.textContent = message;
      feedback.className = `auth-feedback${message ? ` show ${type}` : ''}`;
    };

    const showStep = name => {
      steps.forEach(step => { step.hidden = step.dataset.step !== name; });
      show('');
      const target = root.querySelector(`[data-step="${name}"] input:not([type="hidden"])`);
      window.setTimeout(() => target?.focus(), 0);
    };

    const preferredMethod = () => state.methods.find(item => item.channel === 'sms') || state.methods[0] || null;

    const sendExistingOtp = async () => {
      const ordered = [...state.methods].sort((a, b) => (a.channel === 'sms' ? -1 : 1) - (b.channel === 'sms' ? -1 : 1));
      let lastError = null;
      for (const method of ordered) {
        try {
          const data = await auth.identityRequest({
            action: 'send_otp',
            idNumber: state.idNumber,
            channel: method.channel,
            redirectTo: new URL(next, location.href).toString()
          });
          state.channel = method.channel;
          masked.textContent = data.masked || method.masked || 'your contact';
          showStep('code');
          return true;
        } catch (error) {
          lastError = error;
        }
      }
      if (lastError) throw lastError;
      return false;
    };

    idForm.elements.idNumber.value = state.idNumber;

    idForm.addEventListener('submit', async event => {
      event.preventDefault();
      const button = idForm.querySelector('button[type="submit"]');
      const id = String(idForm.elements.idNumber.value || '').replace(/\D/g, '');
      if (!auth.validSaId(id)) return show('Enter a valid 13-digit South African ID number.');

      state.idNumber = id;
      setLoading(button, true, 'Checking…');
      try {
        const data = await auth.identityRequest({ action: 'lookup', idNumber: id });
        state.status = data.status;
        state.methods = data.methods || [];

        if (data.status === 'new') {
          showStep('new');
          return;
        }

        if (state.preferPassword || !state.methods.length) {
          showStep('password');
          return;
        }

        try {
          await sendExistingOtp();
        } catch (error) {
          showStep('password');
          show(error.message);
        }
      } catch (error) {
        show(error.message);
      } finally {
        setLoading(button, false);
      }
    });

    newForm.addEventListener('submit', async event => {
      event.preventDefault();
      const button = newForm.querySelector('button[type="submit"]');
      const firstName = newForm.elements.firstName.value.trim();
      const lastName = newForm.elements.lastName.value.trim();
      const phone = newForm.elements.phone.value.trim();
      const password = newForm.elements.password.value;
      if (firstName.length < 2) return show('Enter your first name.');
      if (lastName.length < 2) return show('Enter your surname.');
      if (password.length < 8) return show('Use at least 8 characters for your password.');

      setLoading(button, true, 'Continuing…');
      try {
        const data = await auth.identityRequest({ action: 'register_password', idNumber: state.idNumber, firstName, lastName, phone, password });
        await setSession(data.session);
      } catch (error) {
        show(error.message);
        setLoading(button, false);
      }
    });

    codeForm.addEventListener('submit', async event => {
      event.preventDefault();
      const button = codeForm.querySelector('button[type="submit"]');
      const token = String(codeForm.elements.token.value || '').replace(/\D/g, '');
      if (!/^\d{6,8}$/.test(token)) return show('Enter the code we sent you.');

      setLoading(button, true, 'Checking…');
      try {
        const data = await auth.identityRequest({ action: 'verify_otp', idNumber: state.idNumber, channel: state.channel, token });
        await setSession(data.session);
      } catch (error) {
        show(error.message);
        setLoading(button, false);
      }
    });

    root.querySelector('[data-resend]').addEventListener('click', async event => {
      const button = event.currentTarget;
      setLoading(button, true, 'Sending…');
      try {
        const data = await auth.identityRequest({
          action: 'send_otp',
          idNumber: state.idNumber,
          channel: state.channel,
          redirectTo: new URL(next, location.href).toString()
        });
        masked.textContent = data.masked || masked.textContent;
        show('A new code has been sent.', 'success');
      } catch (error) {
        show(error.message);
      } finally {
        setLoading(button, false);
      }
    });

    passwordForm.addEventListener('submit', async event => {
      event.preventDefault();
      const button = passwordForm.querySelector('button[type="submit"]');
      const password = passwordForm.elements.password.value;
      if (password.length < 8) return show('Enter your password.');
      setLoading(button, true, 'Checking…');
      try {
        const data = await auth.identityRequest({ action: 'password_login', idNumber: state.idNumber, password });
        await setSession(data.session);
      } catch (error) {
        show(error.message);
        setLoading(button, false);
      }
    });

    root.querySelector('[data-use-password]').addEventListener('click', () => showStep('password'));
    root.querySelector('[data-use-code]').addEventListener('click', async event => {
      const button = event.currentTarget;
      if (!state.methods.length) return showStep('id');
      setLoading(button, true, 'Sending…');
      try { await sendExistingOtp(); }
      catch (error) { show(error.message); }
      finally { setLoading(button, false); }
    });

    root.querySelectorAll('[data-back-id]').forEach(button => button.addEventListener('click', () => {
      state.preferPassword = false;
      showStep('id');
    }));

    showStep('id');

    (async () => {
      await auth.completePendingProfile();
      const user = await auth.getUser();
      if (user && params.get('stay') !== '1') location.href = next;
    })();
  }

  const passwordUpdate = document.querySelector('#updatePasswordForm');
  if (passwordUpdate) {
    (async () => {
      if (!(await auth.getUser())) location.href = `login.html?next=${encodeURIComponent('update-password.html')}`;
    })();

    passwordUpdate.addEventListener('submit', async event => {
      event.preventDefault();
      const button = passwordUpdate.querySelector('button[type="submit"]');
      const password = passwordUpdate.password.value;
      const confirm = passwordUpdate.confirmPassword.value;
      const showPage = (message, type = 'error') => {
        if (!pageFeedback) return;
        pageFeedback.textContent = message;
        pageFeedback.className = `auth-feedback show ${type}`;
      };
      if (password.length < 8) return showPage('Use at least 8 characters for your password.');
      if (password !== confirm) return showPage('The two passwords do not match.');
      setLoading(button, true, 'Saving…');
      const { error } = await client.auth.updateUser({ password });
      if (error) {
        showPage(error.message);
        setLoading(button, false);
        return;
      }
      passwordUpdate.reset();
      showPage('Password saved.', 'success');
      setLoading(button, false);
      const link = document.querySelector('[data-account-after-reset]');
      if (link) link.hidden = false;
    });
  }
})();

/*
 * KredRun white-label brand bridge
 * ------------------------------------------------------------
 * Reads the lender brand from assets/js/tenant-config.js and exposes a
 * stable window.KREDRUN_BRAND object used by Website, Client Portal and Admin.
 */
(() => {
  const DEFAULT_BRAND = {
    name: 'KredRun',
    wordmark: { prefix: 'Kred', accent: 'Run' },
    mark: 'K',
    logoUrl: '',
    faviconUrl: '',
    tagline: 'Fast. Simple. Responsible.',
    strapline: 'Clear online credit for South Africans.',
    colors: {
      primary: '#0876d8',
      primaryStrong: '#0558ad',
      secondary: '#18b5d6',
      accent: '#56c51f',
      accentStrong: '#38a814',
      navy: '#053963',
      ink: '#0c2947',
      background: '#f3f8fc',
      muted: '#668098',
      line: '#d9e6f0',
      danger: '#c6424f',
      warning: '#d8891d',
      success: '#22955f'
    }
  };

  const tenantBrand = window.KREDRUN_TENANT?.brand || {};
  const BRAND = {
    ...DEFAULT_BRAND,
    ...tenantBrand,
    wordmark: { ...DEFAULT_BRAND.wordmark, ...(tenantBrand.wordmark || {}) },
    colors: { ...DEFAULT_BRAND.colors, ...(tenantBrand.colors || {}) }
  };

  const rgb = hex => {
    const clean = String(hex || '').replace('#', '');
    if (!/^[0-9a-f]{6}$/i.test(clean)) return '';
    return `${parseInt(clean.slice(0, 2), 16)}, ${parseInt(clean.slice(2, 4), 16)}, ${parseInt(clean.slice(4, 6), 16)}`;
  };

  const root = document.documentElement;
  const c = BRAND.colors;
  const tokens = {
    '--brand-primary': c.primary,
    '--brand-primary-strong': c.primaryStrong,
    '--brand-secondary': c.secondary,
    '--brand-accent': c.accent,
    '--brand-accent-strong': c.accentStrong,
    '--brand-navy': c.navy,
    '--brand-ink': c.ink,
    '--brand-background': c.background,
    '--brand-muted': c.muted,
    '--brand-line': c.line,
    '--brand-danger': c.danger,
    '--brand-warning': c.warning,
    '--brand-success': c.success,
    '--brand-primary-rgb': rgb(c.primary),
    '--brand-accent-rgb': rgb(c.accent),
    '--brand-navy-rgb': rgb(c.navy)
  };

  Object.entries(tokens).forEach(([key, value]) => value && root.style.setProperty(key, value));
  root.dataset.brand = BRAND.name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  root.dataset.deliveryMode = window.KREDRUN_TENANT?.deliveryMode || 'bundled';
  root.dataset.websiteTemplate = window.KREDRUN_TENANT?.website?.templateId || 'clean-credit';

  if (BRAND.faviconUrl) {
    let icon = document.querySelector('link[rel="icon"]');
    if (!icon) {
      icon = document.createElement('link');
      icon.rel = 'icon';
      document.head.appendChild(icon);
    }
    icon.href = BRAND.faviconUrl;
  }

  window.KREDRUN_BRAND = Object.freeze(BRAND);
})();

/* Applies the central white-label brand config to static and generated UI. */
(() => {
  const brand = window.KREDRUN_BRAND;
  if (!brand) return;

  const setMark = node => {
    if (!node) return;
    node.dataset.brandMark = '';
    if (brand.logoUrl) {
      node.textContent = '';
      const img = document.createElement('img');
      img.src = brand.logoUrl;
      img.alt = '';
      img.decoding = 'async';
      node.appendChild(img);
    } else {
      node.textContent = brand.mark || String(brand.name || 'K').charAt(0).toUpperCase();
    }
  };

  const setWordmark = node => {
    if (!node) return;
    const prefix = brand.wordmark?.prefix || brand.name;
    const accent = brand.wordmark?.accent || '';
    node.dataset.brandWordmark = '';
    node.innerHTML = `${prefix}${accent ? `<em>${accent}</em>` : ''}`;
  };

  document.querySelectorAll('[data-brand-name]').forEach(node => { node.textContent = brand.name; });
  document.querySelectorAll('[data-brand-mark]').forEach(setMark);
  document.querySelectorAll('[data-brand-wordmark]').forEach(setWordmark);

  document.querySelectorAll('.brand').forEach(node => {
    setMark(node.querySelector('.brand-mark'));
    setWordmark(node.querySelector('span:last-child'));
    node.setAttribute('aria-label', `${brand.name} home`);
  });

  document.querySelectorAll('.admin-brand').forEach(node => {
    setMark(node.querySelector(':scope > span'));
    const label = node.querySelector('strong');
    if (label) label.textContent = brand.name;
    node.setAttribute('aria-label', `${brand.name} administration home`);
  });
  document.querySelectorAll('.loading-mark,.account-boot-mark').forEach(setMark);
  document.querySelectorAll('.mini-brand').forEach(setWordmark);

  document.querySelectorAll('.client-header > .brand').forEach(node => {
    if (!node.querySelector('.brand-mark')) node.textContent = brand.name;
  });

  const topStrip = document.querySelector('.top-strip .container');
  if (topStrip) {
    const strong = topStrip.querySelector('strong');
    const span = topStrip.querySelector('span');
    if (strong && brand.tagline) strong.textContent = brand.tagline;
    if (span && brand.strapline) span.textContent = brand.strapline;
  }

  // Allow template copy to opt in to safe brand-name replacement without tying
  // the core platform to any one landing page structure.
  document.querySelectorAll('[data-brand-replace]').forEach(node => {
    node.textContent = String(node.textContent || '').replaceAll('KredRun', brand.name);
  });
  document.querySelectorAll('.home-eyebrow').forEach(node => {
    if ((node.textContent || '').includes('KredRun')) node.textContent = node.textContent.replaceAll('KredRun', brand.name);
  });

  document.querySelectorAll('.footer-bottom span:first-child').forEach(node => {
    if (/^©/.test(node.textContent || '')) node.textContent = `© ${new Date().getFullYear()} ${brand.name}.`;
  });

  if (document.title.includes('KredRun')) document.title = document.title.replaceAll('KredRun', brand.name);
})();

(() => {
  'use strict';

  const CLOSED_INSTALMENT_STATUSES = new Set(['paid', 'waived']);
  const PAYABLE_LOAN_STATUSES = new Set(['active', 'overdue']);
  const CLOSED_LOAN_STATUSES = new Set(['paid', 'cancelled', 'written_off']);
  const DECIDED_APPLICATION_STATUSES = new Set(['approved', 'declined', 'cancelled']);
  const REVIEWABLE_APPLICATION_STATUSES = new Set(['received', 'under_review']);
  const PAYOUT_MARKABLE_STATUSES = new Set(['ready', 'pending']);

  function roundMoney(value) {
    return Math.round((Number(value) + Number.EPSILON) * 100) / 100;
  }

  function instalmentRemaining(schedule) {
    if (!schedule) return 0;
    return roundMoney(Math.max(0, Number(schedule.amount_due || 0) - Number(schedule.amount_paid || 0)));
  }

  function loanOutstanding(loan) {
    return roundMoney(Number(loan?.outstanding_balance || 0));
  }

  function isInstalmentSettled(schedule) {
    if (!schedule) return true;
    if (CLOSED_INSTALMENT_STATUSES.has(schedule.status)) return true;
    return instalmentRemaining(schedule) <= 0;
  }

  function isCollectableSchedule(schedule, loan) {
    return isLoanPayable(loan) && !isInstalmentSettled(schedule);
  }

  function isLoanPayable(loan) {
    if (!loan) return false;
    if (!PAYABLE_LOAN_STATUSES.has(loan.status)) return false;
    if (loan.payout_status !== 'paid') return false;
    return loanOutstanding(loan) > 0;
  }

  function canRecordInstalmentPayment(schedule, loan) {
    return isCollectableSchedule(schedule, loan);
  }

  function canSendInstalmentRequest(schedule, loan) {
    return isCollectableSchedule(schedule, loan);
  }

  function canSendSettlementRequest(loan) {
    return isLoanPayable(loan);
  }

  function canAddLoanCharge(loan) {
    if (!loan) return false;
    if (CLOSED_LOAN_STATUSES.has(loan.status)) return false;
    return loanOutstanding(loan) > 0 || PAYABLE_LOAN_STATUSES.has(loan.status);
  }

  function canMarkPayoutPaid(loan) {
    if (!loan) return false;
    return PAYABLE_LOAN_STATUSES.has(loan.status)
      && loanOutstanding(loan) > 0
      && PAYOUT_MARKABLE_STATUSES.has(loan.payout_status);
  }

  function clientHasActiveLoan(loans, userId) {
    return (loans || []).some(loan =>
      loan.user_id === userId
      && PAYABLE_LOAN_STATUSES.has(loan.status)
      && loanOutstanding(loan) > 0
    );
  }

  function clientHasPendingApplication(applications, userId) {
    return (applications || []).some(app =>
      app.user_id === userId && REVIEWABLE_APPLICATION_STATUSES.has(app.status)
    );
  }

  function canCreateLoanForClient(userId, loans = []) {
    return !clientHasActiveLoan(loans, userId);
  }

  function canCreateLoanFromApplication(application, existingLoans = []) {
    if (!application) return false;
    if (clientHasActiveLoan(existingLoans, application.user_id)) return false;
    if (DECIDED_APPLICATION_STATUSES.has(application.status) && application.status !== 'approved') return false;
    if (application.status === 'approved') {
      if (existingLoans.some(loan => loan.application_id === application.id)) return false;
    }
    return REVIEWABLE_APPLICATION_STATUSES.has(application.status) || application.status === 'approved';
  }

  function canDeclineApplication(application) {
    return application && REVIEWABLE_APPLICATION_STATUSES.has(application.status);
  }

  function canStartApplicationReview(application) {
    return application?.status === 'received';
  }

  function canCreateManualApplication(applications, userId) {
    return !clientHasPendingApplication(applications, userId);
  }

  function canVerifyDocument(document) {
    return document?.verification_status === 'pending';
  }

  function canRejectDocument(document) {
    return document?.verification_status === 'pending';
  }

  function canChangeLoanStatus(loan, nextStatus) {
    if (!loan || !nextStatus || loan.status === nextStatus) return false;
    if (CLOSED_LOAN_STATUSES.has(loan.status)) return false;
    const balance = loanOutstanding(loan);
    if (nextStatus === 'paid' && balance > 0) return false;
    if (['active', 'overdue'].includes(nextStatus) && balance <= 0) return false;
    if (loan.status === 'paid' && ['active', 'overdue'].includes(nextStatus)) return false;
    return true;
  }

  function collectableDueTotal(schedules, loans, filter) {
    return (schedules || []).filter(schedule => {
      const loan = (loans || []).find(item => item.id === schedule.loan_id);
      return isCollectableSchedule(schedule, loan) && (!filter || filter(schedule, loan));
    }).reduce((sum, schedule) => sum + instalmentRemaining(schedule), 0);
  }

  function guardMessage(rule) {
    return ({
      instalment_settled: 'This instalment is already paid or waived.',
      loan_not_payable: 'This loan is closed, unpaid-out or has no outstanding balance.',
      loan_closed: 'This loan is closed and cannot be changed this way.',
      application_decided: 'This application has already been decided.',
      application_pending: 'This client already has an application awaiting review.',
      loan_already_linked: 'A loan already exists for this application.',
      active_loan_exists: 'This client already has an active loan with an outstanding balance.',
      payout_recorded: 'Payout has already been recorded.',
      payout_not_ready: 'This loan is not ready for payout recording.',
      invalid_status_change: 'This status change is not allowed for the current loan balance.',
      document_not_pending: 'Only pending documents can be reviewed.'
    })[rule] || 'This action is not allowed.';
  }

  window.KredRunBusinessRules = {
    CLOSED_INSTALMENT_STATUSES,
    PAYABLE_LOAN_STATUSES,
    CLOSED_LOAN_STATUSES,
    instalmentRemaining,
    loanOutstanding,
    isInstalmentSettled,
    isCollectableSchedule,
    isLoanPayable,
    canRecordInstalmentPayment,
    canSendInstalmentRequest,
    canSendSettlementRequest,
    canAddLoanCharge,
    canMarkPayoutPaid,
    canCreateLoanForClient,
    canCreateLoanFromApplication,
    canCreateManualApplication,
    canDeclineApplication,
    canStartApplicationReview,
    canVerifyDocument,
    canRejectDocument,
    canChangeLoanStatus,
    collectableDueTotal,
    clientHasActiveLoan,
    clientHasPendingApplication,
    guardMessage
  };
})();

